{
    # Caddy admin API
    admin localhost:2019

    # Email for Let's Encrypt notifications
    email admin@cohezion.duckdns.org
}

cohezion.duckdns.org {
    # TLS via DuckDNS DNS-01 challenge (no port 80 needed)
    tls {
        dns duckdns {env.DUCKDNS_TOKEN}
    }

    # Reverse proxy to vault MCP server
    reverse_proxy localhost:8360 {
        header_up Host {upstream_hostport}
        flush_interval -1
    }

    # Health check endpoint
    respond /caddy-health "OK" 200
}

